 static bool Above(Window upper,Window lower){var expected=new WindowInteropHelper(upper).Handle;var handle=new WindowInteropHelper(lower).Handle;for(int i=0;i<2000&&(handle=GetWindow(handle,3))!=IntPtr.Zero;i++)if(handle==expected)return true;return false;}
 static bool SmoothGlassTransition(string directory,double top)
 {
  BitmapSource Read(string name){var frame=BitmapFrame.Create(new Uri(Path.Combine(directory,name)),BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);return new FormatConvertedBitmap(frame,PixelFormats.Bgra32,null,0);}
  var original=Read("mini-player-expanded.png");var glass=Read("mini-player-expanded-controls.png");int stride=original.PixelWidth*4;var a=new byte[stride*original.PixelHeight];var b=new byte[a.Length];original.CopyPixels(a,stride,0);glass.CopyPixels(b,stride,0);int x=original.PixelWidth*37/100,start=(int)Math.Round(top*2);
  int Difference(int y){int index=y*stride+x*4;return Enumerable.Range(0,3).Max(i=>Math.Abs(a[index+i]-b[index+i]));}
  int jump=0;for(int y=start;y<start+220;y++)jump=Math.Max(jump,Math.Abs(Difference(y)-Difference(y-1)));
  return Difference(start)<=2&&Difference(start+80)>Difference(start+20)+5&&Difference(start+180)>Difference(start+80)+10&&jump<=4;
 }
